import {platforms,sampleRecords,parseCSV,validateCampaign,summary,transition,recoverCampaigns,makeCampaign} from './domain.mjs';
import {initialSolutions,initialLicenses,stepKinds,validateSolution,unlockSolution,snapshotSolution} from './market.mjs';
import {providers,initialConnections,validateConnection,mockConnectionCheck,checkRequirements} from './connectors.mjs';
import {createWorkspaceClient} from './workspace-client.mjs';
import {validateWorkspace,MAX_WORKSPACE_BYTES} from './workspace-schema.mjs';

const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state,storageIssue='',workspaceBusy=false,pendingImport=null;
const workspace=createWorkspaceClient({storage:{getItem:key=>localStorage.getItem(key),setItem:(key,value)=>localStorage.setItem(key,value),removeItem:key=>localStorage.removeItem(key)},onStatus:({kind,message})=>{
  storageIssue=['warning','error'].includes(kind)?message:'';
  const summary=$('#storage-summary');if(summary)summary.textContent=message;
  const status=$('#storage-status');if(status){status.textContent=message;status.dataset.status=kind;}
  const notice=$('#storage-notice');if(notice){notice.textContent=storageIssue;notice.hidden=!storageIssue;}
}});
function seed(){
  const solutions=initialSolutions(),licenses=initialLicenses();
  const a=makeCampaign('youtube','YouTube · channel onboarding');
  const b=makeCampaign('outlook','Outlook · mailbox workspace');
  const c=makeCampaign('amazon','Amazon · marketplace setup');
  for(const item of [a,b,c]){Object.assign(item,snapshotSolution(solutions.find(s=>s.platform===item.platform),licenses));item.bindings={SMS:'mock-sms',CAPTCHA:'mock-captcha'};}
  let done=transition(b,'start');for(let i=0;i<8;i++)done=transition(done,'tick');
  c.records=[{...sampleRecords()[0],id:'amazon-demo'}];
  return {version:1,campaigns:[a,done,c],solutions,licenses,creatorName:'My studio',connections:initialConnections()};
}
state=await workspace.load(seed);const recoveredRunning=state.campaigns.some(c=>c.status==='running');state.campaigns=recoverCampaigns(state.campaigns);
state.connections=state.connections||initialConnections();
function persist(){return workspace.persist(state);}
let page='campaigns',query='',filter='all',marketQuery='',marketGroup='all',wizardStep=0,draft=null,editingId=null,wizardErrors=[],detailId=null,creatorDraft=null,creatorErrors=[];
let connection=null,checking=false;
let connectorDraft=null,connectorErrors=[],connectorResult=null,connectorTesting=false,csrf=null;
const labels={campaigns:'Campaigns',platforms:'Platforms',marketplace:'Marketplace',creators:'Creator studio',activity:'Activity',connectors:'Connectors',connections:'System status',workspace:'Workspace settings'};
function campaignIssues(c){return [...validateCampaign(c),...checkRequirements({requirements:c.requirements},state.connections,c.bindings||{}).map(message=>({field:'connectors',message}))];}
function getP(id){return platforms.find(p=>p.id===id)||platforms[0];}
function mark(p,large=false){return `<span class="platform-mark ${large?'large':''}" style="--platform-color:${p.color}">${esc(p.mark)}</span>`;}
function badge(s){return `<span class="badge ${esc(s)}">${esc(({draft:'Draft',running:'Running',paused:'Paused',stopped:'Stopped',completed:'Completed',pending:'Pending',success:'Completed',review:'Needs review',failure:'Failed'})[s]||s)}</span>`;}
function when(s){return new Date(s).toLocaleDateString(undefined,{month:'short',day:'numeric'});}
function time(s){return new Date(s).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit',second:'2-digit'});}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function price(s){return Number(s.price)===0?'Free':`$${Number(s.price).toFixed(0)}`;}
function owned(s){return state.licenses.some(l=>l.solutionId===s.id);}
function nav(p){page=labels[p]?p:'campaigns';location.hash=page;query='';filter='all';render();}
function heading(title,desc,action=''){return `<div class="page-heading"><div><div class="eyebrow">HYPERACCTS</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;}
function render(){
  document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===page));
  $('#breadcrumb').innerHTML=`Workspace <span>/</span> ${labels[page]}`;
  $('#nav-count').textContent=state.campaigns.length;
  const views={campaigns:campaignsView,platforms:platformsView,marketplace:marketplaceView,creators:creatorsView,activity:activityView,connectors:connectorsView,connections:connectionsView,workspace:workspaceView};
  $('#app').innerHTML=`<div id="storage-notice" class="notice warn" role="status" ${storageIssue?'':'hidden'}>${esc(storageIssue)}</div>`+views[page]()+`<div class="footer-note">Prototype workspace · Simulated execution and purchases · No real accounts are created</div>`;
}
function workspaceView(){return heading('Your workspace, kept safe.','Save your work on this computer and keep a portable backup.')+`<div class="connection-grid"><section class="panel connection-card"><h2>Storage and recovery</h2><p id="storage-status" role="status" data-status="${workspace.status.kind}">${esc(workspace.status.message)}</p><dl><div class="definition"><dt>Campaigns</dt><dd>${state.campaigns.length}</dd></div><div class="definition"><dt>Workflow solutions</dt><dd>${state.solutions.length}</dd></div><div class="definition"><dt>Connection profiles</dt><dd>${state.connections.length}</dd></div><div class="definition"><dt>Workspace format</dt><dd>Version 1</dd></div></dl><button data-action="storage-retry" ${workspaceBusy?'disabled':''}>Retry storage connection</button><p>Desktop saves keep a previous good copy for recovery. If a save is interrupted, the app checks for pending browser changes at startup.</p></section><section class="panel connection-card"><h2>Backup and restore</h2><p>Back up campaigns, workflow definitions, demo unlocks and connection preferences.</p><div class="backup-actions"><button class="primary" data-action="workspace-export">Export workspace backup</button><button data-action="workspace-import" ${workspaceBusy?'disabled':''}>Import backup</button></div><input id="workspace-backup-file" type="file" accept=".json,application/json" hidden><p>Backup files are unencrypted. Provider keys and connection-test credentials are excluded. Keep backups somewhere private.</p><div class="notice">Restoring replaces this workspace after you review the backup. The previous saved workspace remains in the local recovery file.</div></section></div>`;}
function reviewBackup(input){
  if(!input||typeof input!=='object')throw new Error('Choose a valid HyperAccts JSON backup.');
  if(input.format!==undefined&&(input.format!=='hyperaccts-workspace'||input.backupVersion!==1))throw new Error('Unsupported backup format. Choose a HyperAccts version 1 backup.');
  pendingImport=validateWorkspace(input.format?input.state:input);
  $('#backup-review').innerHTML=`<div class="modal-head"><h2 id="backup-title">Restore this workspace?</h2><button data-action="backup-cancel" aria-label="Cancel restore">×</button></div><div class="modal-body"><p>This backup contains <b>${pendingImport.campaigns.length} campaigns</b>, <b>${pendingImport.solutions.length} solutions</b> and <b>${pendingImport.connections.length} connection profiles</b>.</p><p>It will replace the current workspace. Running simulations will be paused. Export the current workspace first if you want a separate copy.</p><p id="backup-error" class="notice warn" role="alert" hidden></p></div><div class="modal-footer"><button data-action="workspace-export">Export current workspace</button><div class="right"><button data-action="backup-cancel">Cancel</button><button class="primary" data-action="backup-confirm">Restore backup</button></div></div>`;
  $('#backup-review').showModal();
}
function campaignsView(){
  const running=state.campaigns.filter(c=>c.status==='running').length;
  const totals=state.campaigns.map(summary),done=totals.reduce((n,s)=>n+s.success,0),review=totals.reduce((n,s)=>n+s.review+s.failure,0);
  return heading('Good workflows. Clear results.','Your campaigns, organized around what you want to get done.','<button class="primary" data-action="new">＋ New campaign</button>')+
  `<div class="stats">${[['Total campaigns',state.campaigns.length,'Across your installed solutions','▦'],['Running now',running,'Local simulations only','↗'],['Completed records',done,'Simulated successful outcomes','✓'],['Needs attention',review,'Review items and failed records','○']].map(([a,b,c,d])=>`<div class="stat"><span class="stat-label">${a}</span><span class="stat-icon">${d}</span><div class="stat-value">${b}</div><div class="stat-note">${c}</div></div>`).join('')}</div>
  <section class="panel"><div class="panel-head"><h2>Your campaigns <span class="badge">${state.campaigns.length}</span></h2><div class="filters"><label class="search"><span class="sr-only">Search campaigns</span><input id="campaign-search" value="${esc(query)}" placeholder="Search campaigns…"></label><select id="campaign-filter" aria-label="Filter campaign status">${['all','draft','running','paused','completed','stopped'].map(s=>`<option value="${s}" ${filter===s?'selected':''}>${s==='all'?'All statuses':s[0].toUpperCase()+s.slice(1)}</option>`).join('')}</select></div></div><div id="campaign-table">${campaignTable()}</div></section>
  <div class="below"><section class="get-started"><div><div class="eyebrow">LESS SETUP. MORE CLARITY.</div><h3>Start with a ready-made solution.</h3><p>Unlock a reusable workflow from a creator, add your data, and make it your own.</p><button data-nav="marketplace">Explore the marketplace ↗</button></div><div class="illustration">◇</div></section><section class="audit-card"><h3>Built from a real software audit</h3><p>Each platform shows what we inspected, what the old API supports, and what still needs testing.</p><button class="text-link" data-nav="platforms">See platform coverage →</button></section></div>`;
}
function campaignTable(){
  const list=state.campaigns.filter(c=>(c.name+' '+getP(c.platform).name).toLowerCase().includes(query.toLowerCase())&&(filter==='all'||c.status===filter));
  if(!list.length)return `<div class="empty"><h3>${state.campaigns.length?'No matching campaigns':'Your first campaign starts here'}</h3><p>${state.campaigns.length?'Try a different search or status.':'Choose an installed solution and add a few mock records.'}</p></div>`;
  return `<div class="table-scroll"><table><thead><tr><th>CAMPAIGN</th><th>PLATFORM</th><th>STATUS</th><th>PROGRESS</th><th>ACTIONS</th></tr></thead><tbody>${list.map(c=>{const s=summary(c),p=getP(c.platform);return `<tr><td><button class="row-name" data-action="details" data-id="${c.id}"><span class="campaign-name">${esc(c.name)}</span><small>${esc(c.solutionTitle||'Local draft')} · v${esc(c.solutionVersion||'0.1.0')}</small></button></td><td><div class="platform-inline">${mark(p)}${esc(p.name)}</div></td><td>${badge(c.status)}</td><td><div class="progress-wrap"><span class="progress-text">${s.done} / ${s.total} records</span><div class="progress-line"><span style="width:${s.total?s.done/s.total*100:0}%"></span></div></div></td><td><div class="table-actions">${c.status==='running'?`<button data-action="pause" data-id="${c.id}">Pause</button>`:c.status==='paused'?`<button data-action="resume" data-id="${c.id}">Resume</button>`:c.status==='draft'||c.status==='stopped'?`<button data-action="start" data-id="${c.id}">Simulate</button>`:`<button data-action="details" data-id="${c.id}">Results</button>`}<button class="ghost" data-action="details" data-id="${c.id}" aria-label="Open ${esc(c.name)}">↗</button></div></td></tr>`;}).join('')}</tbody></table></div>`;
}
function platformsView(){return heading('Nine platforms. One workspace.','Clear capability labels, before you invest time in setup.')+`<div class="notice">Gmail and Apple cover ordinary accounts. Apple Developer and Play Console enrollment are separate proposed workflows. None of these adapters perform live actions in this prototype.</div><div class="platform-grid">${platforms.map(p=>`<article class="platform-card"><div class="platform-title">${mark(p,true)}<div><h3>${p.name}</h3><small>${p.group}</small></div></div><p>${esc(p.note)}</p><div class="card-evidence">${esc(p.evidence)} · ${p.id==='outlook'?'Legacy campaign API available':'No usable live adapter connected'}</div><button data-action="platform-market" data-id="${p.id}">Explore solutions ↗</button></article>`).join('')}</div>`;}
function marketplaceView(){return heading('Expertise, ready to run.','Discover reusable campaign solutions. Unlock once, create your own campaigns.','<button data-nav="creators">Become a creator ↗</button>')+`<div class="market-banner"><div><div class="market-hero-label">THE SOLUTION MARKETPLACE</div><h2>Someone has already solved<br>your next workflow.</h2><p>Browse solutions, inspect their steps, and install the ones that fit your workspace.</p></div><div class="banner-symbol">◈</div></div><div class="market-tools"><label class="search"><span class="sr-only">Search marketplace</span><input id="market-search" value="${esc(marketQuery)}" placeholder="Search solutions or creators…"></label><select id="market-group" aria-label="Filter marketplace">${['all','installed',...new Set(platforms.map(p=>p.group))].map(g=>`<option value="${g}" ${g===marketGroup?'selected':''}>${g==='all'?'All categories':g==='installed'?'Installed':g}</option>`).join('')}</select><small>Demo listings · Prices are examples · No payments</small></div><div id="solution-grid" class="solution-grid">${marketCards()}</div>`;}
function marketCards(){const list=state.solutions.filter(s=>s.status==='published'&&(s.title+' '+s.creator+' '+getP(s.platform).name).toLowerCase().includes(marketQuery.toLowerCase())&&(marketGroup==='all'||marketGroup==='installed'&&owned(s)||getP(s.platform).group===marketGroup));return list.length?list.map(s=>{const p=getP(s.platform);return `<article class="solution-card"><div class="platform-title">${mark(p,true)}<div><h3>${esc(s.title)}</h3><div class="creator-by">by ${esc(s.creator)} · v${esc(s.version)}</div></div></div><p>${esc(s.description)}</p><div>${owned(s)?'<span class="installed-label">✓ Installed</span>':`<span class="badge">${s.steps.length} workflow steps</span>`}</div><div class="solution-meta"><div><b>${price(s)}</b><small>${Number(s.price)?'Example one-time price':'Demo solution'}</small></div><button data-action="solution" data-id="${s.id}">${owned(s)?'Open solution':'View solution'} ↗</button></div></article>`;}).join(''):`<div class="empty"><h3>No solutions found</h3><p>Try another search or category.</p></div>`;}
function creatorsView(){const mine=state.solutions.filter(s=>s.origin==='creator');return heading('Turn your workflow into a product.','Build a solution, package its steps, and preview how it sells.','<button class="primary" data-action="creator-new">＋ Build a solution</button>')+`<div class="notice">Creator publishing is local to this demo. Other users cannot see these listings yet, and no payouts or real purchases occur.</div><div class="stats">${[['Your solutions',mine.length],['Published locally',mine.filter(s=>s.status==='published').length],['Demo unlocks',state.licenses.filter(l=>mine.some(s=>s.id===l.solutionId)).length],['Live revenue','$0']].map(([a,b])=>`<div class="stat"><div class="stat-label">${a}</div><div class="stat-value">${b}</div><div class="stat-note">Prototype workspace</div></div>`).join('')}</div><section class="panel"><div class="panel-head"><h2>Your solution library</h2></div>${mine.length?`<div class="table-scroll"><table><thead><tr><th>SOLUTION</th><th>VERSION</th><th>PRICE</th><th>STATUS</th><th></th></tr></thead><tbody>${mine.map(s=>`<tr><td><b>${esc(s.title)}</b><div class="creator-by">${esc(getP(s.platform).name)} · ${s.steps.length} steps</div></td><td>${esc(s.version)}</td><td>${price(s)}</td><td>${badge(s.status==='published'?'Published locally':'draft')}</td><td><button data-action="creator-edit" data-id="${s.id}">Edit draft</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><h3>Your knowledge could be someone's shortcut.</h3><p>Pick a platform, arrange a few workflow steps, and publish your first demo solution.</p><button class="primary" data-action="creator-new">Build your first solution</button></div>`}</section><div class="below"><section class="audit-card"><h3>1. Build a reusable solution</h3><p>Define the platform, inputs, validation, review steps, and output. Buyers supply their own campaign records.</p></section><section class="audit-card"><h3>2. Version, price, and publish</h3><p>New campaigns pin the solution version and workflow. Editing a listing does not silently rewrite existing campaigns.</p></section></div>`;}
function activityView(){const events=state.campaigns.flatMap(c=>(c.events||[]).map(e=>({...e,campaign:c.name}))).sort((a,b)=>b.time.localeCompare(a.time));return heading('Every step, in view.','Campaign events are kept locally so outcomes are easy to understand.')+`<section class="panel"><div class="panel-head"><h2>Recent activity</h2><span class="badge">Simulation events</span></div><div class="activity-list">${events.length?events.slice(0,100).map(e=>`<div class="activity-row"><time>${when(e.time)}<br>${time(e.time)}</time><div>${esc(e.text)}<small>${esc(e.campaign)}</small></div></div>`).join(''):'<div class="empty">Run a simulation to see activity here.</div>'}</div></section>`;}
function connectionsView(){return heading('Know what is connected.','Keep the new workspace separate from the legacy execution engine.')+`<div class="connection-grid"><section class="panel connection-card"><div class="platform-title"><span class="platform-mark large" style="--platform-color:#4c8260">⇄</span><div><h2>PVA Creator</h2><p>Local, read-only connection check</p></div></div><dl><div class="definition"><dt>Installed version</dt><dd>6.8.5 · inspected September 30, 2026</dd></div><div class="definition"><dt>API coverage</dt><dd>Three platform entries found during the audit</dd></div><div class="definition"><dt>Account APIs</dt><dd>Outlook and Twitter mock additions failed</dd></div><div class="definition"><dt>Access</dt><dd>Audited local calls did not require a key</dd></div></dl><button class="primary" data-action="check-connection" ${checking?'disabled':''}>${checking?'Checking…':'Check connection'}</button><div id="connection-result" class="api-result">${connection?connectionHTML():''}</div><p>This check reads platform and campaign summaries only. It cannot start a legacy campaign.</p></section><section class="panel connection-card"><h2>Marketplace services</h2><div class="notice">The marketplace is a working local demo. Live commerce is a separate build phase.</div><dl><div class="definition"><dt>Creator accounts</dt><dd>Local demo identity</dd></div><div class="definition"><dt>Payments</dt><dd>Not connected</dd></div><div class="definition"><dt>Licenses</dt><dd>Simulated browser-local unlocks</dd></div><div class="definition"><dt>Publication</dt><dd>Local preview only</dd></div><div class="definition"><dt>Live execution</dt><dd>Not connected</dd></div></dl><a class="audit-link" href="/audit-evidence.json" target="_blank" rel="noopener">Open audit evidence ↗</a></section></div>`;}
function connectionHTML(){return connection.ok?`<div class="notice">Connected · ${connection.platforms.length} platforms · ${connection.campaignCount} API-visible campaigns<br>${connection.platforms.map(p=>`${esc(p.name)}: ${esc(p.status)}`).join('<br>')}</div>`:`<div class="notice warn">${esc(connection.message)}</div>`;}

function connectorsView(){
  return heading('Connect once. Reuse everywhere.','SMSPVA and DaisySMS for numbers. 2Captcha for CAPTCHA. Your credentials stay outside creator solutions.','<button class="primary" data-action="connector-new">＋ Add connection</button>')+
  `<div class="notice">SMSPVA, DaisySMS, and 2Captcha support live API-key and balance checks. Campaign runs remain simulations. Other provider profiles are mock-only until their adapters are implemented.</div><section class="panel"><div class="panel-head"><h2>Your connections</h2><span class="badge">Workspace owned</span></div><div class="table-scroll"><table><thead><tr><th>CONNECTION</th><th>PROVIDER</th><th>MODE</th><th>LAST CHECK</th><th></th></tr></thead><tbody>${state.connections.map(c=>{const p=providers.find(p=>p.id===c.provider);return `<tr><td><b>${esc(c.name)}</b><div class="creator-by">${p.category}${c.country?' · '+esc(c.country):''}</div></td><td>${p.name}</td><td>${badge(c.mode==='mock'?'Demo':'Balance check only')}</td><td>${c.checkedAt?`${c.mode==='mock'?'Mock check':`Balance: ${esc(c.balance)}`}<div class="creator-by">${when(c.checkedAt)} ${time(c.checkedAt)}</div>`:'Not tested'}</td><td><button data-action="connector-edit" data-id="${c.id}">Configure</button></td></tr>`;}).join('')}</tbody></table></div></section><h2 style="margin:30px 0 18px">Provider library</h2><div class="solution-grid">${[...providers].sort((a,b)=>(['smspva','daisysms','2captcha'].includes(b.id)?1:0)-(['smspva','daisysms','2captcha'].includes(a.id)?1:0)).map(p=>`<article class="solution-card"><div class="platform-title"><span class="platform-mark large" style="--platform-color:${p.category==='SMS'?'#36856a':'#7b699f'}">${p.mark}</span><div><h3>${p.name}</h3><div class="creator-by">${p.category} ${['smspva','daisysms','2captcha'].includes(p.id)?'· Your default':''}</div></div></div><p>${esc(p.description)}</p><div class="card-evidence">${esc(p.source)}<br>${['smspva','daisysms','2captcha'].includes(p.id)?'Live balance-check adapter included':'Mock profile only; live adapter pending'}</div><div class="solution-meta">${p.docs?`<a href="${p.docs}" target="_blank" rel="noopener" style="font-size:11px">Provider docs ↗</a>`:'<small>API contract unverified</small>'}<button data-action="connector-provider" data-id="${p.id}">Set up</button></div></article>`).join('')}</div>`;
}
function openConnector(id=null,provider='smspva'){
  connectorDraft=id?structuredClone(state.connections.find(c=>c.id===id)):{id:crypto.randomUUID(),provider,name:providers.find(p=>p.id===provider).name+' connection',country:'United States',budget:5,timeout:180,mode:'mock',status:'untested'};
  connectorErrors=[];connectorResult=null;renderConnector();$('#connector-editor').showModal();
}
function renderConnector(){const c=connectorDraft,p=providers.find(p=>p.id===c.provider),live=['smspva','daisysms','2captcha'].includes(p.id);$('#connector-editor').innerHTML=`<div class="modal-head"><div><h2 id="connector-title">${p.name} connector</h2><p>${p.category} · Your workspace, your credentials</p></div><button class="close-btn" data-action="close-connector" aria-label="Close connector editor">×</button></div><div class="modal-body"><div class="form-grid"><label>Connection name<input data-connection="name" value="${esc(c.name)}"></label><label>Mode<select data-connection="mode"><option value="mock" ${c.mode==='mock'?'selected':''}>Mock connection</option>${live?`<option value="balance-only" ${c.mode==='balance-only'?'selected':''}>Live API / balance check only</option>`:''}</select></label>${p.category==='SMS'?`<label>Preferred country<select data-connection="country">${['United States','United Kingdom','Vietnam','Canada','Germany','France','India','Indonesia'].map(v=>`<option ${c.country===v?'selected':''}>${v}</option>`).join('')}</select></label>`:''}<label>Planned spend limit (USD)<input data-connection="budget" type="number" min="0" max="10000" step="0.5" value="${c.budget}"><span class="field-hint">Saved preference; no spending is enabled in this prototype.</span></label><label>Planned wait timeout (seconds)<input data-connection="timeout" type="number" min="10" max="600" value="${c.timeout}"></label>${c.mode==='balance-only'?`<label class="full">API key<input id="provider-api-key" type="password" autocomplete="off" spellcheck="false" placeholder="${c.credentialRef?'Enter again after a server restart, or leave blank to reuse this session':'Paste your '+p.name+' API key'}"><span class="field-hint">Kept in local server memory for this session. Never saved in browser storage, a solution, or GitHub.</span></label>`:''}</div><div class="notice">${c.mode==='mock'?'Mock checks validate the profile without contacting a provider.':'Test connection sends the key directly through your local HyperAccts server to '+p.name+' to read the balance only. It does not order numbers or submit CAPTCHA tasks.'}</div>${connectorErrors.length?`<ul class="error-list">${connectorErrors.map(e=>`<li>${esc(e)}</li>`).join('')}</ul>`:''}<div id="connector-check-result">${connectorResult?`<div class="notice ${connectorResult.ok?'':'warn'}">${esc(connectorResult.message)}${connectorResult.ok&&typeof connectorResult.balance==='number'?`<br>Provider balance: <b>${connectorResult.balance}</b>`:''}</div>`:''}</div></div><div class="modal-footer"><small>${live?'Live balance check available':'Live provider adapter pending'}</small><div class="right"><button data-action="connector-test" ${connectorTesting?'disabled':''}>${connectorTesting?'Checking…':'Test connection'}</button><button class="primary" data-action="connector-save" ${connectorTesting?'disabled':''}>Save connection</button></div></div>`;}
async function testConnector(){
  connectorErrors=validateConnection(connectorDraft);if(connectorErrors.length){renderConnector();return;}
  const apiKey=$('#provider-api-key')?.value||'';
  connectorTesting=true;renderConnector();
  try{
    if(connectorDraft.mode==='mock')connectorResult=mockConnectionCheck(connectorDraft);
    else {if(!csrf){const r=await fetch('/api/session');csrf=(await r.json()).csrf;}
      const r=await fetch(`/api/connectors/${connectorDraft.provider}/check`,{method:'POST',headers:{'content-type':'application/json','x-hyperaccts-token':csrf},body:JSON.stringify({apiKey,credentialRef:connectorDraft.credentialRef})});connectorResult=await r.json();}
    if(connectorResult.ok){connectorDraft.checkedAt=connectorResult.checkedAt;connectorDraft.balance=connectorResult.balance;connectorDraft.status='checked';if(connectorResult.credentialRef)connectorDraft.credentialRef=connectorResult.credentialRef;}
  }catch{connectorResult={ok:false,message:'The local connector service could not be reached. Start HyperAccts and retry.'};}
  connectorTesting=false;renderConnector();
}
function saveConnector(){connectorErrors=validateConnection(connectorDraft);if(connectorErrors.length){renderConnector();return;}const i=state.connections.findIndex(c=>c.id===connectorDraft.id);if(i<0)state.connections.push(structuredClone(connectorDraft));else state.connections[i]=structuredClone(connectorDraft);persist();$('#connector-editor').close();nav('connectors');toast('Connection profile saved.');}
function openWizard(solutionId=null,campaignId=null){
  editingId=campaignId;wizardErrors=[];wizardStep=0;
  if(campaignId){draft=structuredClone(state.campaigns.find(c=>c.id===campaignId));if(['running','paused'].includes(draft.status))return toast('Stop the simulation before editing.');wizardStep=1;}
  else {const available=state.solutions.find(s=>s.id===solutionId&&owned(s))||state.solutions.find(s=>owned(s));if(!available){nav('marketplace');return toast('Install a solution to create a campaign.');}draft=makeCampaign(available.platform,'');Object.assign(draft,snapshotSolution(available,state.licenses));if(solutionId)wizardStep=1;}
  draft.bindings=draft.bindings||{SMS:'mock-sms',CAPTCHA:'mock-captcha'};renderWizard();$('#wizard').showModal();
}
function renderWizard(){
  const p=getP(draft.platform),titles=['Solution','Details','Records','Review'];
  let body='';
  if(wizardStep===0){const available=state.solutions.filter(s=>owned(s));body=`<h3 class="helper-title">Choose an installed solution</h3><div class="choose-grid">${available.map(s=>`<button class="choose-card ${s.id===draft.solutionId?'selected':''}" data-action="choose-solution" data-id="${s.id}">${mark(getP(s.platform))}<span>${esc(s.title)}<small>${esc(s.creator)} · v${s.version}</small></span></button>`).join('')}</div><div class="notice">Need another platform? Install a solution from the marketplace. Your campaign gets its own copy of the workflow and its version.</div>`;}
  if(wizardStep===1)body=`<div class="platform-title" style="margin-bottom:23px">${mark(p,true)}<div><h3>${esc(draft.solutionTitle)}</h3><small>Version ${esc(draft.solutionVersion)} · ${esc(draft.creator)}</small></div></div><div class="form-grid"><label class="full">Campaign name<input id="draft-name" maxlength="80" value="${esc(draft.name)}" placeholder="e.g. ${p.name} · September onboarding"><span class="field-hint">Use a name that explains the purpose of this campaign.</span></label>${p.fields.map(([key,label,type,options])=>`<label>${esc(label)}${type==='select'?`<select data-setting="${key}">${options.split('|').map(v=>`<option ${draft.settings[key]===v?'selected':''}>${esc(v)}</option>`).join('')}</select>`:`<input data-setting="${key}" type="${type}" value="${esc(draft.settings[key]||'')}" placeholder="${type==='email'?'recovery@example.invalid':'Optional in this prototype'}">`}</label>`).join('')}</div>${(draft.requirements||[]).length?`<h3 class="helper-title">Campaign connections</h3><div class="form-grid">${draft.requirements.map(r=>`<label>${r} provider<select data-binding="${r}"><option value="">Choose a connection</option>${state.connections.filter(c=>providers.find(p=>p.id===c.provider)?.category===r).map(c=>`<option value="${c.id}" ${draft.bindings[r]===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>`).join('')}</div>`:''}<div class="notice">Simulation workspace. All records use mock addresses; no passwords, service keys, or payment details are collected.</div>`;
  if(wizardStep===2)body=`<div class="record-toolbar"><button data-action="sample-records">Load sample records</button><button data-action="import-records">Import CSV</button><button data-action="template">Download template</button><button data-action="add-record">＋ Add row</button><small>${draft.records.length} records</small><input type="file" id="csv-file" accept=".csv,text/csv" hidden></div><div class="table-scroll"><table class="records-edit"><thead><tr><th style="width:24%">USERNAME</th><th style="width:36%">MOCK EMAIL</th><th style="width:28%">DEMO OUTCOME</th><th style="width:12%"></th></tr></thead><tbody>${draft.records.map((r,i)=>`<tr><td><input aria-label="Username row ${i+1}" data-record="${i}" data-key="username" value="${esc(r.username)}"></td><td><input aria-label="Mock email row ${i+1}" data-record="${i}" data-key="email" value="${esc(r.email)}"></td><td><select aria-label="Outcome row ${i+1}" data-record="${i}" data-key="mockOutcome">${['success','review','failure'].map(v=>`<option value="${v}" ${r.mockOutcome===v?'selected':''}>${{success:'Complete',review:'Needs review',failure:'Fail'}[v]}</option>`).join('')}</select></td><td><button data-action="remove-record" data-id="${i}" aria-label="Remove row ${i+1}">×</button></td></tr>`).join('')}</tbody></table></div><div class="notice">Choose an outcome for each row to explore success, review, and error handling. Use email addresses ending in <b>.invalid</b>.</div>`;
  if(wizardStep===3){const errors=campaignIssues(draft);body=`<div class="review-box"><div class="review-top">${mark(p,true)}<div><h3>${esc(draft.name||'Untitled campaign')}</h3><p>${esc(draft.solutionTitle)} · v${esc(draft.solutionVersion)}</p></div></div><div class="flow">${(draft.workflow||[]).map((s,i)=>`${i?'<i>→</i>':''}<span>${esc(s.label)}</span>`).join('')}</div><div class="review-grid"><div>Execution<b>Local simulation</b></div><div>Records<b>${draft.records.length} mock records</b></div><div>External actions<b>None</b></div><div>Validation<b>${errors.length?`${errors.length} issues to fix`:'Ready to simulate'}</b></div></div></div><div class="notice">Saving creates a draft. Running a simulation demonstrates record outcomes; it does not operate a real account or a live platform.</div>${errors.length?`<ul class="error-list">${errors.map(e=>`<li>${esc(e.message)}</li>`).join('')}</ul>`:''}`;}
  $('#wizard').innerHTML=`<div class="modal-head"><div><h2 id="wizard-title">${editingId?'Edit campaign':'Create a campaign'}</h2><p>A short path from an idea to a clear result.</p></div><button class="close-btn" data-action="close-wizard" aria-label="Close campaign editor">×</button></div><div class="steps">${titles.map((t,i)=>`<div class="step ${i===wizardStep?'current':i<wizardStep?'done':''}"><b>${i<wizardStep?'✓':i+1}</b>${t}</div>`).join('')}</div><div class="modal-body">${body}${wizardErrors.length?`<ul class="error-list">${wizardErrors.map(e=>`<li>${esc(e)}</li>`).join('')}</ul>`:''}</div><div class="modal-footer"><div>${wizardStep?'<button data-action="wizard-back">← Back</button>':'<small>Installed solutions only</small>'}</div><div class="right"><button data-action="save-draft">Save draft</button>${wizardStep<3?'<button class="primary" data-action="wizard-next">Continue →</button>':`<button class="primary" data-action="save-run" ${campaignIssues(draft).length?'disabled':''}>Save & simulate</button>`}</div></div>`;
}
function saveWizard(run=false){
  if(!draft.name.trim()){wizardStep=1;wizardErrors=['Give this campaign a name before saving.'];renderWizard();return;}
  if(run&&campaignIssues(draft).length){wizardStep=3;renderWizard();return;}
  let saved=structuredClone(draft);saved.status='draft';saved.records=saved.records.map(r=>({...r,status:'pending',message:''}));saved.events=[];
  if(run)saved=transition(saved,'start');
  const at=state.campaigns.findIndex(c=>c.id===saved.id);if(at<0)state.campaigns.unshift(saved);else state.campaigns[at]=saved;
  persist();$('#wizard').close();nav('campaigns');toast(run?'Simulation started.':'Draft saved in this browser.');if(run)openDetails(saved.id);
}
function openDetails(id){detailId=id;renderDetails();if(!$('#details').open)$('#details').showModal();}
function renderDetails(){const c=state.campaigns.find(c=>c.id===detailId);if(!c)return;const s=summary(c),p=getP(c.platform);$('#details').innerHTML=`<div class="modal-head"><div><h2 id="details-title">${esc(c.name)}</h2><p>${p.name} · ${esc(c.solutionTitle)} · v${esc(c.solutionVersion)} · Simulation</p></div><button class="close-btn" data-action="close-details" aria-label="Close campaign details">×</button></div><div class="modal-body"><div class="detail-actions">${badge(c.status)}${c.status==='running'?`<button data-action="pause" data-id="${c.id}">Pause</button>`:c.status==='paused'?`<button data-action="resume" data-id="${c.id}">Resume</button>`:`<button class="primary" data-action="start" data-id="${c.id}">${c.status==='completed'?'Run again':'Simulate'}</button>`}${['running','paused'].includes(c.status)?`<button data-action="stop" data-id="${c.id}">Stop</button>`:`<button data-action="edit" data-id="${c.id}">Edit campaign</button>`}${s.failure&&!['running','paused'].includes(c.status)?`<button data-action="retry" data-id="${c.id}">Retry failed only</button>`:''}<button data-action="export" data-id="${c.id}">Export results</button></div><div class="detail-stats">${[['Records',s.total],['Completed',s.success],['Review',s.review],['Failed',s.failure]].map(([a,b])=>`<div>${a}<b>${b}</b></div>`).join('')}</div><h3 class="helper-title">Installed workflow · pinned to this campaign</h3><div class="flow">${(c.workflow||[]).map((step,i)=>`${i?'<i>→</i>':''}<span>${esc(step.label)}</span>`).join('')}</div><div class="table-scroll" style="margin-top:22px"><table class="details-table"><thead><tr><th>RECORD</th><th>STATUS</th><th>RESULT</th></tr></thead><tbody>${c.records.map(r=>`<tr><td>${esc(r.username)}<div class="creator-by">${esc(r.email)}</div></td><td>${badge(r.status)}</td><td>${esc(r.message||'Waiting for simulation.')}</td></tr>`).join('')}</tbody></table></div><div class="event-log">${(c.events||[]).length?c.events.slice(-12).map(e=>`<div><time>${time(e.time)}</time>${esc(e.text)}</div>`).join(''):'No simulation events yet.'}</div></div><div class="modal-footer"><small>Simulated outcomes only. Retrying uses the same configured demo outcome.</small><button data-action="close-details">Done</button></div>`;}
function doTransition(id,action){try{const index=state.campaigns.findIndex(c=>c.id===id);if(['start','resume','retry'].includes(action)){const issues=campaignIssues(state.campaigns[index]);if(issues.length)throw new Error(issues[0].message);}state.campaigns[index]=transition(state.campaigns[index],action);persist();render();if($('#details').open)renderDetails();}catch(e){toast(e.message);}}
function download(name,text,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function openSolution(id){const s=state.solutions.find(s=>s.id===id),p=getP(s.platform);$('#solution-dialog').innerHTML=`<div class="modal-head"><div class="platform-title">${mark(p,true)}<div><h2 id="solution-title">${esc(s.title)}</h2><p>by ${esc(s.creator)} · Version ${esc(s.version)}</p></div></div><button class="close-btn" data-action="close-solution" aria-label="Close solution">×</button></div><div class="modal-body"><p>${esc(s.description)}</p><div class="permission-list">${s.capabilities.map(v=>`<span>✓ ${esc(v)}</span>`).join('')}</div><h3 class="helper-title">What's inside this solution</h3><div class="solution-steps">${s.steps.map(step=>`<div>${esc(step.label)}<small>${esc(step.kind)}</small></div>`).join('')}</div><div class="notice">${esc(p.note)}</div><p class="money-note">${owned(s)?'Installed in this local workspace.':'Demo checkout records a local unlock only. You will not be charged.'} Live marketplace listings, licenses, seller verification, and payments are not connected.</p></div><div class="modal-footer"><div><b>${price(s)}</b><div class="money-note">${Number(s.price)?'Example one-time price':'Demo solution'}</div></div>${owned(s)?`<button class="primary" data-action="solution-use" data-id="${s.id}">Create a campaign →</button>`:`<button class="primary" data-action="unlock" data-id="${s.id}">${Number(s.price)?'Simulate purchase & unlock':'Install demo solution'}</button>`}</div>`;if(!$('#solution-dialog').open)$('#solution-dialog').showModal();}

function openCreator(id=null){const existing=state.solutions.find(s=>s.id===id&&s.origin==='creator');creatorDraft=existing?structuredClone(existing):{id:crypto.randomUUID(),platform:'gmail',title:'',creator:state.creatorName,version:'1.0.0',price:29,description:'',status:'draft',origin:'creator',evidence:'Creator demo',requirements:[],steps:[{kind:'Collect data',label:'Collect account details'},{kind:'Validate inputs',label:'Check required fields'},{kind:'Owner review',label:'Review the prepared records'},{kind:'Export results',label:'Export the results'}],capabilities:['Mock data only','Local simulation','No external services']};creatorErrors=[];renderCreator();$('#creator-editor').showModal();}
function renderCreator(){const s=creatorDraft;$('#creator-editor').innerHTML=`<div class="modal-head"><div><h2 id="creator-title">Build a campaign solution</h2><p>Package your workflow for the marketplace.</p></div><button class="close-btn" data-action="close-creator" aria-label="Close creator editor">×</button></div><div class="modal-body"><div class="form-grid"><label>Solution title<input data-creator="title" maxlength="70" value="${esc(s.title)}" placeholder="e.g. Gmail onboarding checklist"></label><label>Creator name<input data-creator="creator" maxlength="70" value="${esc(s.creator)}"></label><label>Platform<select data-creator="platform">${platforms.map(p=>`<option value="${p.id}" ${p.id===s.platform?'selected':''}>${p.name}</option>`).join('')}</select></label><label>Version<input data-creator="version" value="${esc(s.version)}" placeholder="1.0.0"></label><label>Example price (USD)<input data-creator="price" type="number" min="0" max="9999" step="1" value="${s.price}"><span class="field-hint">Use 0 for a free demo solution.</span></label><label>Execution<select disabled><option>Local simulation only</option></select></label><label class="full">What does this solution do?<textarea data-creator="description" maxlength="1000" placeholder="Describe who it helps, what it prepares, and what users get back.">${esc(s.description)}</textarea></label></div><fieldset class="connector-requirements"><legend>Connections buyers need</legend>${['SMS','CAPTCHA'].map(r=>`<label><input type="checkbox" data-requirement="${r}" ${(s.requirements||[]).includes(r)?'checked':''}> ${r}</label>`).join('')}<p class="field-hint">Buyers select their own connection. Your API keys never travel with a solution.</p></fieldset><section class="creator-section"><div><h3>Workflow steps</h3><button data-action="add-step" ${s.steps.length>=12?'disabled':''}>＋ Add step</button></div><div class="steps-list">${s.steps.map((step,i)=>`<div class="workflow-step"><span class="step-num">${i+1}</span><select data-step="${i}" data-key="kind" aria-label="Step ${i+1} type">${stepKinds.map(k=>`<option ${k===step.kind?'selected':''}>${k}</option>`).join('')}</select><input data-step="${i}" data-key="label" aria-label="Step ${i+1} label" value="${esc(step.label)}" maxlength="80"><div class="step-actions"><button data-action="step-up" data-id="${i}" ${i===0?'disabled':''} aria-label="Move step ${i+1} up">↑</button><button data-action="step-down" data-id="${i}" ${i===s.steps.length-1?'disabled':''} aria-label="Move step ${i+1} down">↓</button><button data-action="step-remove" data-id="${i}" ${s.steps.length<=2?'disabled':''} aria-label="Remove step ${i+1}">×</button></div></div>`).join('')}</div></section><div class="notice">These are declarative demo steps. The current runner simulates record outcomes; a live workflow engine, custom integrations, branching, and creator code execution are future work.</div>${creatorErrors.length?`<ul class="error-list">${creatorErrors.map(e=>`<li>${esc(e)}</li>`).join('')}</ul>`:''}</div><div class="modal-footer"><small>Publishing makes this visible in your local demo marketplace.</small><div class="right"><button data-action="creator-save">Save draft</button><button class="primary" data-action="creator-publish">Publish demo listing →</button></div></div>`;}
function saveCreator(publish){
  creatorErrors=publish?validateSolution(creatorDraft):(!creatorDraft.title.trim()?['Add a title before saving your draft.']:[]);
  const existing=state.solutions.find(s=>s.id===creatorDraft.id);
  if(publish&&existing?.status==='published'&&existing.version===creatorDraft.version)creatorErrors.push('Increment the version before republishing an existing listing.');
  if(creatorErrors.length){renderCreator();return;}
  const saved=structuredClone(creatorDraft);saved.price=Number(saved.price);saved.status=publish?'published':'draft';if(publish)saved.publishedAt=new Date().toISOString();
  // Keep a published listing available while the creator works on an unpublished revision.
  if(!publish&&existing?.status==='published'){saved.id=crypto.randomUUID();saved.title+=' (draft revision)';}
  const i=state.solutions.findIndex(s=>s.id===saved.id);if(i<0)state.solutions.unshift(saved);else state.solutions[i]=saved;
  state.creatorName=saved.creator;persist();$('#creator-editor').close();nav(publish?'marketplace':'creators');toast(publish?'Published to your local demo marketplace.':'Solution draft saved.');
}

document.addEventListener('click',async e=>{
  const b=e.target.closest('[data-action],[data-nav]');if(!b||b.disabled)return;
  if(b.dataset.nav){nav(b.dataset.nav);return;}
  const a=b.dataset.action,id=b.dataset.id;
  if(['start','pause','resume','stop','retry'].includes(a)){doTransition(id,a);return;}
  switch(a){
    case'workspace-export':try{download('HyperAccts-workspace-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify({format:'hyperaccts-workspace',backupVersion:1,createdAt:new Date().toISOString(),state:validateWorkspace(state)}));}catch(error){toast(error.message);}break;
    case'workspace-import':$('#workspace-backup-file').click();break;
    case'backup-cancel':if(!workspaceBusy){pendingImport=null;$('#backup-review').close();}break;
    case'backup-confirm':{
      if(workspaceBusy||!pendingImport)break;
      workspaceBusy=true;b.disabled=true;
      try{const restored=structuredClone(pendingImport);restored.campaigns=recoverCampaigns(restored.campaigns);state=await workspace.restore(restored);pendingImport=null;$('#backup-review').close();nav('workspace');toast('Backup restored.');}
      catch(error){const el=$('#backup-error');el.hidden=false;el.textContent=error.message;}
      finally{workspaceBusy=false;b.disabled=false;render();}break;
    }
    case'storage-retry':{
      if(workspaceBusy)break;workspaceBusy=true;b.disabled=true;
      try{state=await workspace.load(()=>state);state.campaigns=recoverCampaigns(state.campaigns);}
      finally{workspaceBusy=false;render();}break;
    }
    case'connector-new':openConnector();break;
    case'connector-provider':openConnector(null,id);break;
    case'connector-edit':openConnector(id);break;
    case'connector-test':await testConnector();break;
    case'connector-save':saveConnector();break;
    case'close-connector':if(!connectorTesting)$('#connector-editor').close();break;
    case'new':openWizard();break;
    case'details':openDetails(id);break;
    case'edit':$('#details').close();openWizard(null,id);break;
    case'close-details':$('#details').close();break;
    case'close-wizard':$('#wizard').close();break;
    case'choose-solution':{const s=state.solutions.find(s=>s.id===id);draft.platform=s.platform;draft.settings={};Object.assign(draft,snapshotSolution(s,state.licenses));renderWizard();break;}
    case'wizard-next':wizardErrors=[];if(wizardStep===1&&!draft.name.trim()){wizardErrors=['Give this campaign a name.'];renderWizard();break;}wizardStep=Math.min(3,wizardStep+1);renderWizard();break;
    case'wizard-back':wizardStep=Math.max(0,wizardStep-1);wizardErrors=[];renderWizard();break;
    case'save-draft':saveWizard(false);break;
    case'save-run':saveWizard(true);break;
    case'sample-records':draft.records=sampleRecords();wizardErrors=[];renderWizard();break;
    case'add-record':if(draft.records.length<500){draft.records.push({id:crypto.randomUUID(),username:'',email:'',firstName:'',lastName:'',mockOutcome:'success',status:'pending'});renderWizard();}break;
    case'remove-record':draft.records.splice(Number(id),1);renderWizard();break;
    case'import-records':$('#csv-file').click();break;
    case'template':download('mock-records.csv','username,email,firstName,lastName,mockOutcome\r\nmorgan.demo,morgan@example.invalid,Morgan,Demo,success\r\nriver.demo,river@example.invalid,River,Demo,review\r\nalex.demo,alex@example.invalid,Alex,Demo,failure\r\n','text/csv');break;
    case'export':{const c=state.campaigns.find(c=>c.id===id);download('campaign-results.json',JSON.stringify({mode:'simulation',...c},null,2));break;}
    case'platform-market':marketQuery=getP(id).name;marketGroup='all';nav('marketplace');break;
    case'solution':openSolution(id);break;
    case'close-solution':$('#solution-dialog').close();break;
    case'solution-use':$('#solution-dialog').close();openWizard(id);break;
    case'unlock':{const s=state.solutions.find(s=>s.id===id);try{state.licenses=unlockSolution(s,state.licenses);persist();render();openSolution(id);toast('Demo solution unlocked. No payment was taken.');}catch(error){toast(error.message);}break;}
    case'creator-new':openCreator();break;
    case'creator-edit':openCreator(id);break;
    case'close-creator':$('#creator-editor').close();break;
    case'creator-save':saveCreator(false);break;
    case'creator-publish':saveCreator(true);break;
    case'add-step':creatorDraft.steps.push({kind:'Owner review',label:'New review step'});renderCreator();break;
    case'step-remove':creatorDraft.steps.splice(Number(id),1);renderCreator();break;
    case'step-up':case'step-down':{const i=Number(id),j=i+(a==='step-up'?-1:1);[creatorDraft.steps[i],creatorDraft.steps[j]]=[creatorDraft.steps[j],creatorDraft.steps[i]];renderCreator();break;}
    case'check-connection':checking=true;render();try{const r=await fetch('/api/pva/status');if(!r.ok)throw new Error('The local read-only connection check is unavailable.');connection=await r.json();}catch(error){connection={ok:false,message:error.message};}checking=false;render();break;
  }
});
document.addEventListener('input',e=>{
  const t=e.target;
  if(t.id==='campaign-search'){query=t.value;$('#campaign-table').innerHTML=campaignTable();}
  if(t.id==='market-search'){marketQuery=t.value;$('#solution-grid').innerHTML=marketCards();}
  if(t.dataset.connection&&connectorDraft){connectorDraft[t.dataset.connection]=['budget','timeout'].includes(t.dataset.connection)?Number(t.value):t.value;if(t.dataset.connection==='mode'){connectorResult=null;connectorDraft.checkedAt=null;renderConnector();}}
  if(t.dataset.binding&&draft)draft.bindings[t.dataset.binding]=t.value;
  if(t.dataset.requirement&&creatorDraft){const req=new Set(creatorDraft.requirements||[]);t.checked?req.add(t.dataset.requirement):req.delete(t.dataset.requirement);creatorDraft.requirements=[...req];}
  if(t.id==='draft-name'&&draft)draft.name=t.value;
  if(t.dataset.setting&&draft)draft.settings[t.dataset.setting]=t.value;
  if(t.dataset.record!==undefined&&draft)draft.records[Number(t.dataset.record)][t.dataset.key]=t.value;
  if(t.dataset.creator&&creatorDraft)creatorDraft[t.dataset.creator]=t.dataset.creator==='price'?Number(t.value):t.value;
  if(t.dataset.step!==undefined&&creatorDraft)creatorDraft.steps[Number(t.dataset.step)][t.dataset.key]=t.value;
});
document.addEventListener('change',async e=>{
  const t=e.target;
  if(t.id==='campaign-filter'){filter=t.value;$('#campaign-table').innerHTML=campaignTable();}
  if(t.id==='market-group'){marketGroup=t.value;$('#solution-grid').innerHTML=marketCards();}
  if(t.id==='csv-file'&&t.files[0]){try{if(t.files[0].size>1024*1024)throw new Error('Choose a CSV smaller than 1 MB.');draft.records=parseCSV(await t.files[0].text());wizardErrors=[];}catch(error){wizardErrors=[error.message];}renderWizard();}
  if(t.id==='workspace-backup-file'&&t.files[0]){try{if(t.files[0].size>MAX_WORKSPACE_BYTES+1024)throw new Error('Choose a backup smaller than 4 MiB.');reviewBackup(JSON.parse(await t.files[0].text()));}catch(error){toast(error instanceof SyntaxError?'The selected file is not valid JSON. Your workspace has not changed.':error.message);}finally{t.value='';}}
});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(labels[p]&&p!==page){page=p;render();}});
setInterval(()=>{
  if(workspaceBusy)return;
  let changed=false;state.campaigns=state.campaigns.map(c=>{if(c.status!=='running')return c;changed=true;return transition(c,'tick');});
  if(changed){persist();if(page==='campaigns'&&!$('#wizard').open)render();if(page==='activity')render();if($('#details').open)renderDetails();}
},1400);
page=labels[location.hash.slice(1)]?location.hash.slice(1):'campaigns';render();
if(recoveredRunning)persist();
window.addEventListener('beforeunload',event=>{if(workspace.pending){event.preventDefault();event.returnValue='';}});
